operations.schema:
input SetAssociationNameInput {
  nameEn: String!
  nameDe: String
}

input SetAssociationSeatInput {
  seatCity: String!
  seatCanton: String!
  registeredAddress: String
}

operations.reducer:
state.seatCity = action.input.seatCity;
state.seatCanton = action.input.seatCanton;
if (action.input.registeredAddress) {
  state.registeredAddress = action.input.registeredAddress;
  state.registeredAddressConfirmed = true;
}

operations.schema:
input SetFoundingDateInput {
  foundingDate: Date!
}

input SetFiscalDetailsInput {
  fiscalYearEnd: String
  membershipFee: String
  primaryLanguage: PrimaryLanguage
}

operations.reducer:
if (action.input.fiscalYearEnd) state.fiscalYearEnd = action.input.fiscalYearEnd;
if (action.input.membershipFee) state.membershipFee = action.input.membershipFee;
if (action.input.primaryLanguage) state.primaryLanguage = action.input.primaryLanguage;

operations.schema:
input SetPurposeInput {
  purposeEn: String!
  purposeDe: String
}

operations.reducer:
const member = {
  id: action.input.id,
  type: action.input.type,
  name: action.input.name,
  nationalityOrCountry: action.input.nationalityOrCountry,
  residenceOrCity: action.input.residenceOrCity,
  representative: action.input.representative || null,
  ethereumAddress: action.input.ethereumAddress || null,
  incorporationSignedAt: null,
};
state.members.push(member);
state.belowRecommendedMemberCount = state.members.length < 3;
updatePersonalunionFlag(state);

const idx = state.members.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new MemberNotFoundError(`Member ${action.input.id} not found`);
const member = state.members[idx];
if (action.input.type) member.type = action.input.type;
if (action.input.name) member.name = action.input.name;
if (action.input.nationalityOrCountry) member.nationalityOrCountry = action.input.nationalityOrCountry;
if (action.input.residenceOrCity) member.residenceOrCity = action.input.residenceOrCity;
if (action.input.representative !== undefined && action.input.representative !== null) member.representative = action.input.representative;
updatePersonalunionFlag(state);

operations.schema:
input RemoveMemberInput {
  id: OID!
}

operations.reducer:
const idx = state.members.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new MemberNotFoundError(`Member ${action.input.id} not found`);
state.members.splice(idx, 1);
state.belowRecommendedMemberCount = state.members.length < 3;
updatePersonalunionFlag(state);

operations.schema:
input SetMemberEthereumAddressInput {
  id: OID!
  ethereumAddress: EthereumAddress!
}

operations.reducer:
const idx = state.members.findIndex((m) => m.id === action.input.id);
if (idx === -1)
  throw new MemberNotFoundForAddressError(`Member ${action.input.id} not found`);
const member = state.members[idx];
if (member.incorporationSignedAt)
  throw new MemberAlreadySignedError(
    `Member ${action.input.id} has already signed and cannot change address`,
  );
const normalized = action.input.ethereumAddress.toLowerCase();
const clash = state.members.some(
  (m) =>
    m.id !== action.input.id &&
    m.ethereumAddress &&
    m.ethereumAddress.toLowerCase() === normalized,
);
if (clash)
  throw new DuplicateEthereumAddressError(
    `Ethereum address is already assigned to another member`,
  );
member.ethereumAddress = action.input.ethereumAddress;

if (!state.boardMembers) state.boardMembers = [];
const boardMember = {
  id: action.input.id,
  type: action.input.type,
  name: action.input.name,
  nationalityOrCountry: action.input.nationalityOrCountry,
  residenceOrCity: action.input.residenceOrCity,
  representative: action.input.representative || null,
  ethereumAddress: null,
  incorporationSignedAt: null,
};
state.boardMembers.push(boardMember);
updatePersonalunionFlag(state);

if (!state.boardMembers) state.boardMembers = [];
const idx = state.boardMembers.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new BoardMemberNotFoundError(`Board member ${action.input.id} not found`);
const member = state.boardMembers[idx];
if (action.input.type) member.type = action.input.type;
if (action.input.name) member.name = action.input.name;
if (action.input.nationalityOrCountry) member.nationalityOrCountry = action.input.nationalityOrCountry;
if (action.input.residenceOrCity) member.residenceOrCity = action.input.residenceOrCity;
if (action.input.representative !== undefined && action.input.representative !== null) member.representative = action.input.representative;
updatePersonalunionFlag(state);

operations.schema:
input RemoveBoardMemberInput {
  id: OID!
}

operations.reducer:
if (!state.boardMembers) state.boardMembers = [];
const idx = state.boardMembers.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new BoardMemberNotFoundError(`Board member ${action.input.id} not found`);
state.boardMembers.splice(idx, 1);
updatePersonalunionFlag(state);

operations.schema:
input CopyFoundingMembersToBoardInput {
  confirm: Boolean!
}

operations.reducer:
state.boardMembers = state.members.map((member) => ({
  id: member.id,
  type: member.type,
  name: member.name,
  nationalityOrCountry: member.nationalityOrCountry,
  residenceOrCity: member.residenceOrCity,
  representative: member.representative || null,
  ethereumAddress: null,
  incorporationSignedAt: null,
}));
updatePersonalunionFlag(state);

state.chairName = action.input.chairName;
state.chairRole = action.input.chairRole;
state.secretaryName = action.input.secretaryName;
state.secretaryRole = action.input.secretaryRole;
state.meetingIsOnline = action.input.meetingIsOnline;
state.meetingVenue = action.input.meetingIsOnline ? null : action.input.meetingVenue || null;
state.counselName = action.input.counselName || null;

operations.schema:
input StartStage_2Input {
  startedAt: DateTime!
}

input SetStage2DocumentMarkdownInput {
  documentType: Stage2DocumentType!
  markdown: String!
}

operations.reducer:
const target = action.input.documentType === "AOA" ? (state.aoaDocument || (state.aoaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "FOUNDING_MINUTES" ? (state.foundingMinutesDocument || (state.foundingMinutesDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "REG_GA" ? (state.regGaDocument || (state.regGaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "DISSOLUTION_RESOLUTION" ? (state.dissolutionResolutionDocument || (state.dissolutionResolutionDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : (state.mpaDocument || (state.mpaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false}));
if (target.isLocked) return;
target.markdown = action.input.markdown;

operations.schema:
input MarkStage2DocumentSignedInput {
  documentType: Stage2DocumentType!
  signedAt: DateTime!
}

operations.reducer:
const target = action.input.documentType === "AOA" ? (state.aoaDocument || (state.aoaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "FOUNDING_MINUTES" ? (state.foundingMinutesDocument || (state.foundingMinutesDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "REG_GA" ? (state.regGaDocument || (state.regGaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "DISSOLUTION_RESOLUTION" ? (state.dissolutionResolutionDocument || (state.dissolutionResolutionDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : (state.mpaDocument || (state.mpaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false}));
if (target.isLocked) return;
target.isSigned = true;
target.signedAt = action.input.signedAt;
target.isLocked = true;
if (state.aoaDocument?.isSigned && state.foundingMinutesDocument?.isSigned && !state.incorporationCompletedAt) {
  state.incorporationCompletedAt = action.input.signedAt;
}

const phase = state.phases.find((p) => p.phaseNumber === action.input.phaseNumber);
if (!phase) throw new PhaseNotFoundError(`Phase ${action.input.phaseNumber} not found`);
phase.status = action.input.status;
if (action.input.documentsGenerated !== undefined && action.input.documentsGenerated !== null) phase.documentsGenerated = action.input.documentsGenerated;
if (action.input.documentsSigned !== undefined && action.input.documentsSigned !== null) phase.documentsSigned = action.input.documentsSigned;
if (action.input.completedDate) phase.completedDate = action.input.completedDate;

operations.schema:
input AdvancePhaseInput {
  completedDate: Date!
}

operations.reducer:
const current = state.phases.find((p) => p.phaseNumber === state.currentPhase);
if (!current) throw new PhaseNotFoundError(`Current phase ${state.currentPhase} not found`);
current.status = "COMPLETE";
current.completedDate = action.input.completedDate;
const next = state.phases.find((p) => p.phaseNumber === (state.currentPhase ?? 0) + 1);
if (next) {
  next.status = "IN_PROGRESS";
  state.currentPhase = next.phaseNumber;
}

operations.schema:
input AddNoteInput {
  note: String!
}

operations.reducer:
if (!state.dissolution) {
  state.dissolution = { dissolutionDate: null, resolutionForm: null, assetRecipient: null, executingPersons: null, remainingAssetsSummary: null };
}
if (action.input.dissolutionDate) state.dissolution.dissolutionDate = action.input.dissolutionDate;
if (action.input.resolutionForm) state.dissolution.resolutionForm = action.input.resolutionForm;
if (action.input.assetRecipient) state.dissolution.assetRecipient = action.input.assetRecipient;
if (action.input.executingPersons) state.dissolution.executingPersons = action.input.executingPersons;
if (action.input.remainingAssetsSummary) state.dissolution.remainingAssetsSummary = action.input.remainingAssetsSummary;

if (!state.contributorAgreements) state.contributorAgreements = [];
const agreement = state.contributorAgreements.find((a) => a.id === action.input.id);
if (!agreement) throw new ContributorAgreementNotFoundError(`Contributor agreement ${action.input.id} not found`);
if (action.input.contractorIsEntity !== undefined && action.input.contractorIsEntity !== null) agreement.contractorIsEntity = action.input.contractorIsEntity;
if (action.input.termType) agreement.termType = action.input.termType;
if (action.input.contractorName) agreement.contractorName = action.input.contractorName;
if (action.input.contractorNationality) agreement.contractorNationality = action.input.contractorNationality;
if (action.input.contractorAddress) agreement.contractorAddress = action.input.contractorAddress;
if (action.input.entityName) agreement.entityName = action.input.entityName;
if (action.input.entityType) agreement.entityType = action.input.entityType;
if (action.input.entityJurisdiction) agreement.entityJurisdiction = action.input.entityJurisdiction;
if (action.input.role) agreement.role = action.input.role;
if (action.input.contractDate) agreement.contractDate = action.input.contractDate;
if (action.input.workStartDate) agreement.workStartDate = action.input.workStartDate;
if (action.input.workEndDate) agreement.workEndDate = action.input.workEndDate;
if (action.input.terminationNoticePeriod) agreement.terminationNoticePeriod = action.input.terminationNoticePeriod;
if (action.input.sowNumber) agreement.sowNumber = action.input.sowNumber;
if (action.input.services) agreement.services = action.input.services;
if (action.input.fteHours) agreement.fteHours = action.input.fteHours;
if (action.input.compensation) agreement.compensation = action.input.compensation;
if (action.input.denominationType) agreement.denominationType = action.input.denominationType;
if (action.input.denominationCurrency) agreement.denominationCurrency = action.input.denominationCurrency;

operations.schema:
input RemoveContributorAgreementInput {
  id: OID!
}

operations.reducer:
if (!state.contributorAgreements) state.contributorAgreements = [];
const idx = state.contributorAgreements.findIndex((a) => a.id === action.input.id);
if (idx === -1) throw new ContributorAgreementNotFoundError(`Contributor agreement ${action.input.id} not found`);
state.contributorAgreements.splice(idx, 1);

operations.schema:
input SetContributorAgreementMarkdownInput {
  id: OID!
  markdown: String!
}

operations.reducer:
if (!state.contributorAgreements) state.contributorAgreements = [];
const agreement = state.contributorAgreements.find((a) => a.id === action.input.id);
if (!agreement) throw new ContributorAgreementNotFoundError(`Contributor agreement ${action.input.id} not found`);
if (!agreement.generatedDocument) agreement.generatedDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false};
if (agreement.generatedDocument.isLocked) return;
agreement.generatedDocument.markdown = action.input.markdown;

operations.schema:
input MarkContributorAgreementSignedInput {
  id: OID!
  signedAt: DateTime!
}

operations.reducer:
if (!state.contributorAgreements) state.contributorAgreements = [];
const agreement = state.contributorAgreements.find((a) => a.id === action.input.id);
if (!agreement) throw new ContributorAgreementNotFoundError(`Contributor agreement ${action.input.id} not found`);
if (!agreement.generatedDocument) agreement.generatedDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false};
if (agreement.generatedDocument.isLocked) return;
agreement.generatedDocument.isSigned = true;
agreement.generatedDocument.signedAt = action.input.signedAt;
agreement.generatedDocument.isLocked = true;

operations.schema:
input SignForIncorporationInput {
  signedAt: DateTime!
}

operations.reducer:
const signerAddress = action.context?.signer?.user.address;
if (state.incorporationCompletedAt)
  throw new AlreadyIncorporatedError("Entity is already incorporated");
if (!signerAddress)
  throw new MissingSignerError("No signer address on the action");
if (state.members.length === 0)
  throw new NoFoundingMembersError("No founding members to sign for");
const normalized = signerAddress.toLowerCase();
const member = state.members.find(
  (m) => m.ethereumAddress && m.ethereumAddress.toLowerCase() === normalized,
);
if (!member)
  throw new SignerNotFoundingMemberError(
    "Signer address does not match any founding member",
  );
if (member.incorporationSignedAt)
  throw new AlreadySignedError("This founding member has already signed");
member.incorporationSignedAt = action.input.signedAt;
const allSigned = state.members.every((m) => m.incorporationSignedAt);
if (allSigned) {
  state.incorporationCompletedAt = action.input.signedAt;
}
